insert into private.disposal_guidance (id, category_id, action_summary, requirements, where_summary, escalation_url, active, review_status) values
  ('35ec3dab-20fb-542b-8940-a9c5b5193f13', 'cf89b030-da88-5bc1-a369-a9528db1d927', 'Take the mattress to an applicable City resident waste-drop-off facility and follow the attendant''s direction to the regular-refuse roll-off container or transfer-station pit floor.', array['Bag the mattress when possible.', 'Follow facility signs and attendant directions; facilities may operate differently.', 'Resident vehicle and two-load-per-day rules apply.']::text[], 'An applicable City resident waste-drop-off facility; this record does not select an individual site.', 'https://www.honolulu.gov/env/ref/waste-drop-off-rules-residents/', true, 'approved'),
  ('29f2904d-14a4-579f-bb30-20bd64b862ae', 'b1b9980c-1fd2-54f4-bf25-a6eeb54b0bb3', 'Take a household chair or table to an applicable City resident waste-drop-off facility and place it with regular refuse as directed.', array['Material that can be disassembled or broken down must be less than 6 feet long and weigh less than 60 pounds.', 'Follow facility signs and attendant directions; facilities may operate differently.', 'Resident vehicle and two-load-per-day rules apply.']::text[], 'Regular-refuse roll-off container or transfer-station pit floor at an applicable City facility.', 'https://www.honolulu.gov/env/ref/waste-drop-off-rules-residents/', true, 'approved'),
  ('f218e031-b5a9-5578-bc0b-abb99bb78a4f', 'afea61b7-714f-5375-8fe0-4115262cd759', 'Fasten the rug or carpeting and take it to an applicable City resident waste-drop-off facility for regular refuse.', array['Rugs and carpeting must be fastened.', 'Material that can be cut or broken down must be less than 6 feet long and weigh less than 60 pounds.', 'Follow facility signs and attendant directions.']::text[], 'Regular-refuse roll-off container or transfer-station pit floor at an applicable City facility.', 'https://www.honolulu.gov/env/ref/waste-drop-off-rules-residents/', true, 'approved'),
  ('26aab8d5-f9f9-57e2-9924-8e47720b716d', '4597a66e-9a15-5c85-abad-ad221d750c9b', 'Take a listed green-waste material to an applicable City resident drop-off facility and place it loosely in the designated green-waste area.', array['Do not put green waste in plastic bags.', 'Stumps and logs must be less than 9 inches in diameter.', 'Natural Christmas trees must not be flocked.', 'General size, vehicle, load, and attendant rules apply.']::text[], 'The designated green-waste roll-off container or area at an applicable City drop-off site.', 'https://www.honolulu.gov/env/ref/waste-drop-off-rules-residents/', true, 'approved'),
  ('7cfe6a7d-2c5c-52e4-8730-7518524fa8f3', '367e815d-7d7a-54fd-b08d-b49d84a350fc', 'Take a source-listed large household appliance to an applicable City resident drop-off facility and place it in the separate appliance storage area as directed.', array['The limit is two large appliances per month.', 'Only household types are accepted; commercial equipment is not accepted.', 'Follow facility signs and attendant directions.']::text[], 'The separate large-appliance storage area at an applicable City resident drop-off facility.', 'https://www.honolulu.gov/env/ref/waste-drop-off-rules-residents/', true, 'approved'),
  ('b8fad8b3-bd13-56ac-9a7b-8d9adee96a4e', '484ffd75-ec80-5164-8085-eb22434d303c', 'Take passenger or light-truck tires, with or without rims, to an accepting City disposal site.', array['The limit is four tires per month.', 'Keʻehi Transfer Station does not accept tires.', 'Heavy-truck and equipment tires are not accepted under this rule.']::text[], 'City disposal sites except Keʻehi Transfer Station.', 'https://www.honolulu.gov/env/ref/waste-drop-off-rules-residents/', true, 'approved'),
  ('9e241765-2812-56e5-81e6-d7889c85b882', '7fcc6bcb-aec8-56d9-8274-c395b40ed7e3', 'Put an alkaline or other single-use household battery in regular refuse.', array['Use this instruction only when the battery is known to be alkaline or single-use.']::text[], 'Regular household refuse.', 'https://www.honolulu.gov/env/ref/waste-drop-off-rules-residents/', true, 'approved'),
  ('aeccbaba-02cd-5318-8b86-e4cda00489e7', 'b8d70624-d6c7-5309-a6b0-7d918c149656', 'Tape the terminals of a source-listed standalone rechargeable battery, place it in a clear plastic bag, and take it to an applicable City resident waste-drop-off facility.', array['The battery must be standalone.', 'The source-listed chemistries are lithium, lithium-ion, nickel-metal-hydride, and nickel-cadmium.', 'Tape the terminals and place the battery in a clear plastic bag.']::text[], 'An applicable City resident waste-drop-off facility; individual-site availability is not specified by this record.', 'https://www.honolulu.gov/env/ref/waste-drop-off-rules-residents/', true, 'approved'),
  ('7723f3c9-fe61-5cb4-8dea-956f49439939', 'a6120b58-44d6-5596-b90e-dcd4718d34fb', 'Take a lead-acid car or motorcycle battery to an applicable City resident waste-drop-off facility.', array['Only lead-acid car and motorcycle batteries are covered.', 'Heavy-equipment and electric-vehicle batteries are not accepted under this rule.', 'Follow facility signs and attendant directions.']::text[], 'An applicable City resident waste-drop-off facility; individual-site availability is not specified by this record.', 'https://www.honolulu.gov/env/ref/waste-drop-off-rules-residents/', true, 'approved'),
  ('603e748f-fc06-526d-8950-1a7aaa8c818b', 'aba78d31-c83e-558d-a27d-706edc8fa9f6', 'Take a source-listed household propane tank or cylinder to an applicable City resident waste-drop-off facility, whether empty, partially full, or full.', array['Supported tank sizes are the source-stated 5 gallons and 20 gallons; supported cylinders are the source-stated 16 ounces.', 'Commercial-grade compressed gas, industrial tanks, oxygen cylinders, and SCUBA tanks are prohibited.', 'Follow facility signs and attendant directions.']::text[], 'An applicable City resident waste-drop-off facility; individual-site availability is not specified by this record.', 'https://www.honolulu.gov/env/ref/waste-drop-off-rules-residents/', true, 'approved'),
  ('f0f3dc61-d3bd-5719-ab55-22466c59106a', '17e8864c-fb95-5ded-a858-57072f104b66', 'Take a source-qualified television to a City e-waste bin at a listed transfer station or convenience center for recycling.', array['The viewable screen must be 9 inches or larger.', 'The device must fit the television or video-display definition on the official accepted-items list.', 'Verify current site availability before travel.']::text[], 'City e-waste bins at the transfer stations and convenience centers listed on the official page.', 'https://www.honolulu.gov/env/city-ewaste-dropbins/', true, 'approved'),
  ('48dd7866-61dd-55ba-9e02-3d9b79cc3a7d', '7257f210-6afb-5870-897c-0d4f2b1cc2fd', 'Take a computer or computer-related device that appears explicitly on the City''s accepted list to a City e-waste bin for recycling.', array['Computers, portable computers, printers, and monitors must meet the accepted-item descriptions on the official page.', 'Electronics integrated into motor vehicles or larger industrial, commercial, medical, or listed household equipment are excluded.', 'Verify current site availability before travel.']::text[], 'City e-waste bins at the transfer stations and convenience centers listed on the official page.', 'https://www.honolulu.gov/env/city-ewaste-dropbins/', true, 'approved'),
  ('3583810d-08ca-5057-8605-f8d472b76e2f', '7f5ab92b-1e09-5b4f-b25b-1669707ab268', 'Put a non-CFL light bulb from a small residential quantity in the trash.', array['Use this instruction only when the bulb is known not to be a compact fluorescent bulb or tube.', 'Large quantities require calling the City''s Refuse Division for instructions.']::text[], 'Regular household trash.', 'https://www.honolulu.gov/env/ref/hhw-2/', true, 'approved'),
  ('85f23c9e-d25e-591f-9f07-57e7d3767c81', 'cf05bba9-39e5-5840-8835-9bbf32ad8372', 'Encase household medical sharps in a rigid screw-top plastic container, close it securely, and put it in the trash.', array['Use a rigid plastic container with a screw top.', 'Close the container securely to prevent spillage.', 'Large quantities require calling the City''s Refuse Division for instructions.']::text[], 'Regular household trash after secure containment.', 'https://www.honolulu.gov/env/ref/hhw-2/', true, 'approved'),
  ('9cb91c82-8f89-52c3-ba95-e727e15f282d', '71d9a953-ae9a-510a-9ada-40b2084e0ed8', 'Schedule a City household-hazardous-waste appointment for a compact fluorescent bulb or tube and follow the live registration instructions.', array['Drop-off is by appointment only.', 'Only registered items are accepted, subject to the current event limit and instructions.', 'Event dates, registration status, and deadlines must be checked on the live page.']::text[], 'A scheduled City household-hazardous-waste drop-off event.', 'https://www.honolulu.gov/env/ref/hhw-2/', true, 'approved');
insert into private.official_sources (id, stable_id, organization, title, url, authority_level, government_domain, first_retrieved_on, research_checked_on, apparent_updated_on, date_basis, last_verified_on, review_by, review_cadence_days, review_status, verification_notes) values
  ('9cef0435-1c80-5aed-a103-0e3f6ee0f824', 'src-hnl-resident-drop-off', 'City and County of Honolulu Department of Environmental Services', 'Rules and Guidelines for Residents', 'https://www.honolulu.gov/env/ref/waste-drop-off-rules-residents/', 'city_primary', 'honolulu.gov', date '2026-09-05', date '2026-09-05', date '2025-04-22', 'Official City WordPress metadata reports a modified timestamp of 2025-04-22.', date '2026-09-05', date '2026-12-04', 90, 'approved', 'Project-owner approval and second-pass live-source verification were completed on 2026-09-05; all cited sections remained supported.'),
  ('27c65615-b7cd-50e5-be34-32d013201e9f', 'src-hnl-city-ewaste', 'City and County of Honolulu Department of Environmental Services', 'E-waste Recycling at City Disposal Sites', 'https://www.honolulu.gov/env/city-ewaste-dropbins/', 'city_primary', 'honolulu.gov', date '2026-09-05', date '2026-09-05', null, 'No stable publication or update date was displayed on the inspected page.', date '2026-09-05', date '2026-12-04', 90, 'approved', 'Project-owner approval and second-pass live-source verification were completed on 2026-09-05; the accepted-item, excluded-item, and destination lists remain supported, and the VOIP/telephone contradiction remains excluded.'),
  ('3e941d00-689a-508e-81af-3ce43e747875', 'src-hnl-household-hazardous-waste', 'City and County of Honolulu Department of Environmental Services', 'Household Hazardous Waste (HHW)', 'https://www.honolulu.gov/env/ref/hhw-2/', 'city_primary', 'honolulu.gov', date '2026-09-05', date '2026-09-05', null, 'The page displays time-sensitive event information but no stable publication or update date.', date '2026-09-05', date '2026-10-05', 30, 'approved', 'Project-owner approval and second-pass live-source verification were completed on 2026-09-05; durable guidance excludes changing event dates and requires live registration details to be checked.');
insert into private.source_evidence (id, stable_id, source_id, category_id, guidance_id, locator, supporting_summary, claim_scope, research_checked_on, reviewed_on, reviewer_ref, review_status) values
  ('ef91529c-44b9-5852-bda1-4efecdac6c4a', 'ev-mattresses-drop-off', '9cef0435-1c80-5aed-a103-0e3f6ee0f824', 'cf89b030-da88-5bc1-a369-a9528db1d927', '35ec3dab-20fb-542b-8940-a9c5b5193f13', 'Rules and Guidelines for Residents > Regular Refuse', 'The page lists mattresses as acceptable regular refuse, directs regular refuse to a roll-off container or transfer-station pit floor, and requests bags when possible.', 'Resident mattress drop-off only; no curbside-pickup claim.', date '2026-09-05', date '2026-09-05', 'project-owner-human-review', 'approved'),
  ('bcc53d47-8b4f-5d5d-87dc-58d1c165520a', 'ev-household-chairs-tables', '9cef0435-1c80-5aed-a103-0e3f6ee0f824', 'b1b9980c-1fd2-54f4-bf25-a6eeb54b0bb3', '29f2904d-14a4-579f-bb30-20bd64b862ae', 'Rules and Guidelines for Residents > Preparing to Dispose Your Waste; Regular Refuse', 'The page lists chairs and tables as acceptable regular refuse and gives a less-than-6-foot and less-than-60-pound preparation rule for material that can be disassembled or broken down.', 'Household chairs and tables delivered under the resident drop-off rules.', date '2026-09-05', date '2026-09-05', 'project-owner-human-review', 'approved'),
  ('59a2a63c-ae2d-5982-a71f-7fc476344d94', 'ev-rugs-carpeting', '9cef0435-1c80-5aed-a103-0e3f6ee0f824', 'afea61b7-714f-5375-8fe0-4115262cd759', 'f218e031-b5a9-5578-bc0b-abb99bb78a4f', 'Rules and Guidelines for Residents > Preparing to Dispose Your Waste; Regular Refuse', 'The page lists fastened rugs and carpeting as acceptable regular refuse and gives general size and weight preparation rules for material that can be cut or broken down.', 'Fastened residential rugs and carpeting delivered under the resident drop-off rules.', date '2026-09-05', date '2026-09-05', 'project-owner-human-review', 'approved'),
  ('82e6a6da-c3b6-54cc-95f8-ca487296eefc', 'ev-green-waste', '9cef0435-1c80-5aed-a103-0e3f6ee0f824', '4597a66e-9a15-5c85-abad-ad221d750c9b', '26aab8d5-f9f9-57e2-9924-8e47720b716d', 'Rules and Guidelines for Residents > Green Waste', 'The page directs listed green waste to a designated area without plastic bags and lists grass, leaves, branches, trimmings, palm fronds, qualifying stumps/logs, and unflocked natural Christmas trees.', 'Only source-listed residential green-waste materials and stated preparation limits.', date '2026-09-05', date '2026-09-05', 'project-owner-human-review', 'approved'),
  ('898ab463-df16-51a4-9165-44e4c1fb4213', 'ev-large-appliances', '9cef0435-1c80-5aed-a103-0e3f6ee0f824', '367e815d-7d7a-54fd-b08d-b49d84a350fc', '7cfe6a7d-2c5c-52e4-8730-7518524fa8f3', 'Rules and Guidelines for Residents > Large Appliances', 'The page directs listed large appliances to separate storage, limits residents to two per month, and accepts household types rather than commercial equipment.', 'Only the household appliance types explicitly listed by the City page.', date '2026-09-05', date '2026-09-05', 'project-owner-human-review', 'approved'),
  ('82b6e3de-388d-5831-8c9a-5a30c26730a2', 'ev-passenger-light-truck-tires', '9cef0435-1c80-5aed-a103-0e3f6ee0f824', '484ffd75-ec80-5164-8085-eb22434d303c', 'b8fad8b3-bd13-56ac-9a7b-8d9adee96a4e', 'Rules and Guidelines for Residents > Tires (with or without rims)', 'The page accepts up to four passenger or light-truck tires per month, with or without rims, at City disposal sites other than Keʻehi Transfer Station; heavy-truck and equipment tires are excluded.', 'Residential passenger and light-truck tires only.', date '2026-09-05', date '2026-09-05', 'project-owner-human-review', 'approved'),
  ('407a5fc0-a579-5688-8ee7-1f7d18b84d5b', 'ev-alkaline-single-use-batteries', '9cef0435-1c80-5aed-a103-0e3f6ee0f824', '7fcc6bcb-aec8-56d9-8274-c395b40ed7e3', '9e241765-2812-56e5-81e6-d7889c85b882', 'Rules and Guidelines for Residents > Battery', 'The battery section directs alkaline and single-use batteries to regular refuse.', 'Known household alkaline and single-use batteries only.', date '2026-09-05', date '2026-09-05', 'project-owner-human-review', 'approved'),
  ('ce250817-2385-5bcb-a17c-6c86d9482b0f', 'ev-standalone-rechargeable-batteries', '9cef0435-1c80-5aed-a103-0e3f6ee0f824', 'b8d70624-d6c7-5309-a6b0-7d918c149656', 'aeccbaba-02cd-5318-8b86-e4cda00489e7', 'Rules and Guidelines for Residents > Battery', 'The page limits its rechargeable-battery instruction to standalone lithium, lithium-ion, nickel-metal-hydride, and nickel-cadmium batteries and requires taped terminals and a clear plastic bag.', 'Source-listed standalone rechargeable batteries only.', date '2026-09-05', date '2026-09-05', 'project-owner-human-review', 'approved'),
  ('541d3413-df40-5e65-960a-d044edfa1a46', 'ev-lead-acid-batteries', '9cef0435-1c80-5aed-a103-0e3f6ee0f824', 'a6120b58-44d6-5596-b90e-dcd4718d34fb', '7723f3c9-fe61-5cb4-8dea-956f49439939', 'Rules and Guidelines for Residents > Battery; Prohibited Items', 'The page accepts lead-acid car and motorcycle batteries, excludes heavy-equipment batteries, and prohibits electric-vehicle batteries.', 'Lead-acid car and motorcycle batteries under the resident drop-off rules.', date '2026-09-05', date '2026-09-05', 'project-owner-human-review', 'approved'),
  ('80af2786-8734-50cb-b6c7-97a7af5e6e28', 'ev-household-propane-containers', '9cef0435-1c80-5aed-a103-0e3f6ee0f824', 'aba78d31-c83e-558d-a27d-706edc8fa9f6', '603e748f-fc06-526d-8950-1a7aaa8c818b', 'Rules and Guidelines for Residents > Compressed Gas; Prohibited Items', 'The compressed-gas section accepts empty, partially full, or full propane tanks in the source-stated 5- and 20-gallon sizes and 16-ounce propane cylinders; the prohibited list excludes commercial-grade and other industrial gas containers, oxygen tanks, and SCUBA tanks.', 'Only the household propane container sizes explicitly listed by the City page.', date '2026-09-05', date '2026-09-05', 'project-owner-human-review', 'approved'),
  ('4b510711-4911-587e-9aec-32ebb87ae8ec', 'ev-televisions-ewaste', '27c65615-b7cd-50e5-be34-32d013201e9f', '17e8864c-fb95-5ded-a858-57072f104b66', 'f0f3dc61-d3bd-5719-ab55-22466c59106a', 'E-waste Recycling at City Disposal Sites > Acceptable items; Disposal method', 'The page accepts television or video-display devices with a viewable screen of 9 inches or larger and says accepted items may go to City e-waste bins at its listed transfer stations and convenience centers for recycling.', 'Televisions meeting the source''s display definition and size threshold.', date '2026-09-05', date '2026-09-05', 'project-owner-human-review', 'approved'),
  ('e86966a9-1f75-5f29-8752-5e3d85714e19', 'ev-computers-peripherals-ewaste', '27c65615-b7cd-50e5-be34-32d013201e9f', '7257f210-6afb-5870-897c-0d4f2b1cc2fd', '48dd7866-61dd-55ba-9e02-3d9b79cc3a7d', 'E-waste Recycling at City Disposal Sites > Acceptable items; Unacceptable items; Disposal method', 'The page lists computers, printers, monitors, laptops, tablets, peripherals, routers, modems, hard drives, and other named computer-related devices as accepted for City e-waste recycling, while excluding electronics integrated into vehicles or larger industrial, commercial, medical, or listed household equipment.', 'Only computer and peripheral types represented by the category aliases and explicitly listed by the source.', date '2026-09-05', date '2026-09-05', 'project-owner-human-review', 'approved'),
  ('b094a94d-54cf-5303-a0de-1517a074fd9e', 'ev-non-cfl-light-bulbs', '3e941d00-689a-508e-81af-3ce43e747875', '7f5ab92b-1e09-5b4f-b25b-1669707ab268', '3583810d-08ca-5057-8605-f8d472b76e2f', 'Household Hazardous Waste > Disposal of HHW > Put In Trash Can', 'The small-quantity disposal table explicitly includes non-CFL light bulbs in the put-in-trash route and directs large quantities of household hazardous waste to call the City for instructions.', 'Small residential quantities of light bulbs known not to be compact fluorescent bulbs or tubes.', date '2026-09-05', date '2026-09-05', 'project-owner-human-review', 'approved'),
  ('4e517afc-7142-5afd-9f80-a8939b9c2786', 'ev-household-medical-sharps', '3e941d00-689a-508e-81af-3ce43e747875', 'cf05bba9-39e5-5840-8835-9bbf32ad8372', '85f23c9e-d25e-591f-9f07-57e7d3767c81', 'Household Hazardous Waste > Disposal of HHW > Put In Trash Can', 'The small-quantity disposal table includes medical sharps in the trash route and instructs residents to encase sharps in a rigid screw-top plastic container and close containers securely.', 'Small residential quantities of medical sharps after source-specified containment.', date '2026-09-05', date '2026-09-05', 'project-owner-human-review', 'approved'),
  ('ca83e8ff-9e31-57a2-b2db-e674ff54567a', 'ev-compact-fluorescent-lamps', '3e941d00-689a-508e-81af-3ce43e747875', '71d9a953-ae9a-510a-9ada-40b2084e0ed8', '9cb91c82-8f89-52c3-ba95-e727e15f282d', 'Household Hazardous Waste > Disposal of HHW > Schedule an Appointment to Drop-Off', 'The page lists compact fluorescent bulbs and tubes for appointment drop-off and says only registered items are accepted under the live event instructions.', 'Residential compact fluorescent bulbs and tubes using the City appointment process; no durable event date is asserted.', date '2026-09-05', date '2026-09-05', 'project-owner-human-review', 'approved');
